<?php
declare(strict_types=1);
require __DIR__.'/includes/config.php';require __DIR__.'/includes/live.php';require __DIR__.'/includes/shell.php';require __DIR__.'/includes/reptile_core.php';
$uid=ir_current_user_id();
$species=[];$animals=[];
try{$st=$pdo->prepare('SELECT id,latinsky_nazev,cesky_nazev FROM wp_ir2_druhy WHERE user_id=? AND merged_into_id IS NULL ORDER BY latinsky_nazev');$st->execute([$uid]);$species=$st->fetchAll()?:[];$st=$pdo->prepare("SELECT id,jmeno_kod,latinsky_nazev,kategorie,druh_id FROM wp_ir2_zvirata WHERE user_id=? AND ".ir_status_active_sql('wp_ir2_zvirata')." ORDER BY COALESCE(NULLIF(latinsky_nazev,''),jmeno_kod),jmeno_kod");$st->execute([$uid]);$animals=$st->fetchAll()?:[];}catch(Throwable){}
if($_SERVER['REQUEST_METHOD']==='POST'){
 ir_verify_csrf();$action=(string)($_POST['action']??'');
 try{
  if($action==='save_rotation'){
   $speciesId=ir_int($_POST['druh_id']??0);if(!$speciesId)throw new RuntimeException('Vyber druh.');$check=$pdo->prepare('SELECT id FROM wp_ir2_druhy WHERE user_id=? AND id=?');$check->execute([$uid,$speciesId]);if(!$check->fetchColumn())throw new RuntimeException('Druh nebyl nalezen.');
   $target=(string)($_POST['cil']??'adult');if(!in_array($target,['all','mlade','juvenile','subadult','adult','breeding'],true))$target='adult';$name=trim((string)($_POST['nazev']??''))?:'Hlavní rotace';$active=!empty($_POST['aktivni'])?1:0;
   $names=(array)($_POST['step_name']??[]);$types=(array)($_POST['step_type']??[]);$notes=(array)($_POST['step_note']??[]);$steps=[];foreach($names as $i=>$n){$n=trim((string)$n);if($n==='')continue;$steps[]=['name'=>$n,'type'=>trim((string)($types[$i]??'Vlastní'))?:'Vlastní','note'=>trim((string)($notes[$i]??''))];}if(!$steps)throw new RuntimeException('Rotace musí mít alespoň jeden krok.');
   $pdo->beginTransaction();$pdo->prepare('INSERT INTO wp_ir2_suplement_rotace(user_id,druh_id,cil,nazev,aktivni) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE nazev=VALUES(nazev),aktivni=VALUES(aktivni),upraveno=CURRENT_TIMESTAMP')->execute([$uid,$speciesId,$target,$name,$active]);$q=$pdo->prepare('SELECT id FROM wp_ir2_suplement_rotace WHERE user_id=? AND druh_id=? AND cil=? LIMIT 1');$q->execute([$uid,$speciesId,$target]);$rid=(int)$q->fetchColumn();$pdo->prepare('DELETE FROM wp_ir2_suplement_kroky WHERE user_id=? AND rotace_id=?')->execute([$uid,$rid]);$in=$pdo->prepare('INSERT INTO wp_ir2_suplement_kroky(user_id,rotace_id,poradi,typ,nazev,poznamka) VALUES(?,?,?,?,?,?)');foreach($steps as $i=>$step)$in->execute([$uid,$rid,$i+1,$step['type'],$step['name'],$step['note']!==''?$step['note']:null]);$pdo->prepare('DELETE FROM wp_ir2_suplement_stav WHERE user_id=? AND rotace_id=?')->execute([$uid,$rid]);$pdo->commit();
   $q=$pdo->prepare('SELECT id FROM wp_ir2_zvirata WHERE user_id=? AND druh_id=?');$q->execute([$uid,$speciesId]);foreach($q->fetchAll(PDO::FETCH_COLUMN)?:[] as $aid)ir_resync_feed_task($pdo,$uid,(int)$aid);ir_flash('success','Suplementační rotace byla uložena a další krmení v Plánovači přepočítána.');ir_redirect('supplements.php');
  }
  if($action==='delete_rotation'){
   $rid=ir_int($_POST['rotation_id']??0);$q=$pdo->prepare('SELECT druh_id FROM wp_ir2_suplement_rotace WHERE user_id=? AND id=?');$q->execute([$uid,$rid]);$speciesId=(int)$q->fetchColumn();if(!$speciesId)throw new RuntimeException('Rotace nebyla nalezena.');$pdo->beginTransaction();$pdo->prepare('DELETE FROM wp_ir2_suplement_stav WHERE user_id=? AND rotace_id=?')->execute([$uid,$rid]);$pdo->prepare('DELETE FROM wp_ir2_suplement_kroky WHERE user_id=? AND rotace_id=?')->execute([$uid,$rid]);$pdo->prepare('DELETE FROM wp_ir2_suplement_rotace WHERE user_id=? AND id=?')->execute([$uid,$rid]);$pdo->commit();$q=$pdo->prepare('SELECT id FROM wp_ir2_zvirata WHERE user_id=? AND druh_id=?');$q->execute([$uid,$speciesId]);foreach($q->fetchAll(PDO::FETCH_COLUMN)?:[] as $aid)ir_resync_feed_task($pdo,$uid,(int)$aid);ir_flash('success','Rotace byla odstraněna.');ir_redirect('supplements.php');
  }
  if($action==='save_independent'){
   $animalId=ir_int($_POST['animal_id']??0);$animal=ir_animal($pdo,$uid,$animalId);if(!$animal)throw new RuntimeException('Vyber zvíře.');$name=trim((string)($_POST['supplement_name']??''));if($name==='')throw new RuntimeException('Vyplň suplement.');$days=max(1,min(3650,ir_int($_POST['interval_days']??30)));$priority=max(1,min(200,ir_int($_POST['priority']??100)));$start=(string)($_POST['start_date']??date('Y-m-d'));if(!strtotime($start))throw new RuntimeException('Neplatné datum.');$task='Suplementace: '.$name;$marker='[IR-SUPP-PRIORITY:'.$priority.']';$pdo->prepare("UPDATE wp_ir2_planovac SET stav='Hotovo' WHERE user_id=? AND zvire_id=? AND stav='Aktivní' AND nazev_ukolu=?")->execute([$uid,$animalId,$task]);$pdo->prepare("INSERT INTO wp_ir2_planovac(user_id,zvire_id,nazev_ukolu,kategorie,datum_termin,priorita,stav,opakovani,interval_hodnota,poznamka) VALUES(?,?,?,'Suplementace',?,'Vysoká','Aktivní','interval',?,?)")->execute([$uid,$animalId,$task,$start,$days,$marker.' Nezávislý suplement s prioritou před běžnou rotací.']);ir_resync_feed_task($pdo,$uid,$animalId);ir_flash('success','Nezávislý suplement byl přidán do Plánovače.');ir_redirect('supplements.php');
  }
  if($action==='delete_independent'){$taskId=ir_int($_POST['task_id']??0);$q=$pdo->prepare("SELECT zvire_id FROM wp_ir2_planovac WHERE user_id=? AND id=? AND nazev_ukolu LIKE 'Suplementace:%'");$q->execute([$uid,$taskId]);$animalId=(int)$q->fetchColumn();if(!$animalId)throw new RuntimeException('Interval nebyl nalezen.');$pdo->prepare('DELETE FROM wp_ir2_planovac WHERE user_id=? AND id=?')->execute([$uid,$taskId]);ir_resync_feed_task($pdo,$uid,$animalId);ir_flash('success','Nezávislý interval byl odstraněn.');ir_redirect('supplements.php');}
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('IR action: '.$e->getMessage());$error=$e instanceof PDOException?'Změnu se nepodařilo uložit. Zkus to znovu.':$e->getMessage();}
}
$rotations=[];$independent=[];
try{$st=$pdo->prepare("SELECT r.*,d.latinsky_nazev,d.cesky_nazev FROM wp_ir2_suplement_rotace r JOIN wp_ir2_druhy d ON d.id=r.druh_id AND d.user_id=r.user_id WHERE r.user_id=? ORDER BY r.aktivni DESC,d.latinsky_nazev,r.cil");$st->execute([$uid]);foreach($st->fetchAll()?:[] as $r){$q=$pdo->prepare('SELECT * FROM wp_ir2_suplement_kroky WHERE user_id=? AND rotace_id=? ORDER BY poradi,id');$q->execute([$uid,(int)$r['id']]);$r['steps']=$q->fetchAll()?:[];$rotations[]=$r;}$st=$pdo->prepare("SELECT p.*,z.jmeno_kod,z.latinsky_nazev FROM wp_ir2_planovac p JOIN wp_ir2_zvirata z ON z.id=p.zvire_id AND z.user_id=p.user_id WHERE p.user_id=? AND p.stav='Aktivní' AND p.nazev_ukolu LIKE 'Suplementace:%' ORDER BY p.datum_termin,p.id");$st->execute([$uid]);$independent=$st->fetchAll()?:[];}catch(Throwable){}
$labels=['all'=>'Všechny kategorie','mlade'=>'Mláďata','juvenile'=>'Juvenile','subadult'=>'Subadult','adult'=>'Adult','breeding'=>'Chovná zvířata'];
ir_page_start('Suplementační rotace','settings');echo ir_back('settings.php','Zpět do nastavení');if(!empty($error))echo '<div class="flash danger">'.ir_e($error).'</div>';
?>
