<?php foreach($rotations as $r):?><article class="supplement-card"><header><div><strong><?=ir_e((string)$r['nazev'])?></strong><small><i><?=ir_e((string)$r['latinsky_nazev'])?></i> · <?=ir_e($labels[$r['cil']]??(string)$r['cil'])?></small></div><span class="status-pill <?=$r['aktivni']?'amber':''?>"><?=$r['aktivni']?'Aktivní':'Pauza'?></span></header><div class="rotation-chain"><?php foreach($r['steps'] as $i=>$step):?><span><b><?=$i+1?></b><strong><?=ir_e((string)($step['nazev']?:$step['typ']))?></strong><small><?=ir_e((string)$step['typ'])?></small></span><?php endforeach;?></div><footer><span>Posun po skutečném krmení</span><form method="post" onsubmit="return confirm('Odstranit rotaci?')"><?=ir_csrf_field()?><input type="hidden" name="rotation_id" value="<?=$r['id']?>"><button class="btn tiny danger" name="action" value="delete_rotation">Smazat</button></form></footer></article><?php endforeach;if(!$rotations):?><div class="empty-state">Zatím bez rotace.</div><?php endif;?></div>
</section>
<aside class="stack">
<form class="panel glow-panel form-panel" method="post"><?=ir_csrf_field()?><input type="hidden" name="action" value="save_rotation"><header class="panel-head"><div><span class="panel-kicker">ROTATION BUILDER</span><h2>Nová / přepsat rotaci</h2></div><button class="btn primary">Uložit</button></header><div class="form-grid cols-2"><label>Druh<select name="druh_id" required><option value="">Vyber druh…</option><?php foreach($species as $sp):?><option value="<?=$sp['id']?>"><?=ir_e((string)$sp['latinsky_nazev'])?></option><?php endforeach;?></select></label><label>Vývojová kategorie<select name="cil"><?php foreach($labels as $k=>$v):?><option value="<?=$k?>" <?=$k==='adult'?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label>Název<input name="nazev" value="Hlavní rotace"></label><label class="check-line"><input type="checkbox" name="aktivni" value="1" checked><span>Aktivní rotace</span></label></div><div class="rotation-builder" data-rotation-builder><?php for($i=0;$i<6;$i++):?><div class="rotation-builder-row"><b><?=$i+1?></b><input name="step_name[]" placeholder="<?=['Dendrocare','Calcium + D3','Bez suplementu','Dendrocare','Calcium bez D3','Bez suplementu'][$i]?>"><select name="step_type[]"><option>Multivitamin</option><option>Calcium+D3</option><option>Calcium</option><option>Bez</option><option>Vitamin A</option><option>Vlastní</option></select><input name="step_note[]" placeholder="Poznámka"></div><?php endfor;?></div></form>
<form class="panel glow-panel form-panel" method="post"><?=ir_csrf_field()?><input type="hidden" name="action" value="save_independent"><header class="panel-head"><div><span class="panel-kicker">PRIORITA</span><h2>Nezávislý suplement</h2></div></header><div class="form-grid cols-2"><label>Zvíře<select name="animal_id" required><option value="">Vyber zvíře…</option><?php foreach($animals as $a):?><option value="<?=$a['id']?>"><?=ir_e((string)$a['latinsky_nazev'])?> · <?=ir_e((string)$a['jmeno_kod'])?></option><?php endforeach;?></select></label><label>Suplement<input name="supplement_name" required placeholder="Vitamin A"></label><label>Každých dní<input type="number" min="1" name="interval_days" value="30"></label><label>Priorita<input type="number" min="1" max="200" name="priority" value="100"></label><label>První termín<input type="date" name="start_date" value="<?=date('Y-m-d')?>"></label></div><button class="btn secondary">Přidat do Plánovače</button></form>
